package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.History;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The pools per sheet, and their members: people on the sheet, each with a share percent. */
@Repository
public class PoolStore {

    /** A pool as stored. */
    public record Pool(long id, String name) {
    }

    /** A member of a pool: the person, or the pool (personId null, memberPoolId set), the name, the share,
     *  whether the person is retired (a retirement date set; never for a pool), and the dates the membership
     *  counts from and to (null for no bound). */
    public record Member(long poolId, Long personId, Long memberPoolId, String name, BigDecimal share,
            boolean retired, LocalDate from, LocalDate to) {

        /** Whether the membership's dates include the day. */
        public boolean covers(LocalDate day) {
            return (from == null || !day.isBefore(from)) && (to == null || !day.isAfter(to));
        }
    }

    private final JdbcTemplate jdbc;

    public PoolStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's pools, in the order they were added; as of the date when one is given (see {@link History}). */
    public List<Pool> list(String sheetId, LocalDate on) {
        String pool = on == null ? "pool" : History.asOf("pool", "id", on);
        return jdbc.query("SELECT id, name FROM " + pool + " WHERE sheet_id = ? ORDER BY id",
                (rs, i) -> new Pool(rs.getLong("id"), rs.getString("name")), sheetId);
    }

    /** The members of the sheet's pools, by pool id, each pool's in the order they were added. */
    public Map<Long, List<Member>> members(String sheetId, LocalDate on) {
        String member = on == null ? "pool_member" : History.asOf("pool_member", "id", on);
        String person = on == null ? "person" : History.asOf("person", "id", on);
        String pool = on == null ? "pool" : History.asOf("pool", "id", on);
        Map<Long, List<Member>> found = new LinkedHashMap<>();
        jdbc.query("SELECT pool_member.pool_id, pool_member.person_id, pool_member.member_pool_id, person.name,"
                + " pool.name AS pool_name, pool_member.share, person.retired_from, pool_member.from_date,"
                + " pool_member.to_date FROM " + member
                + " LEFT JOIN " + person + " ON person.id = pool_member.person_id"
                + " LEFT JOIN " + pool + " ON pool.id = pool_member.member_pool_id"
                + " WHERE pool_member.sheet_id = ? AND (person.id IS NOT NULL OR pool.id IS NOT NULL)"
                + " ORDER BY pool_member.id", rs -> {
                    Long personId = rs.getObject("person_id") == null ? null : rs.getLong("person_id");
                    Long memberPoolId = rs.getObject("member_pool_id") == null ? null : rs.getLong("member_pool_id");
                    Member m = new Member(rs.getLong("pool_id"), personId, memberPoolId,
                            personId != null ? rs.getString("name") : rs.getString("pool_name"),
                            rs.getBigDecimal("share"), rs.getObject("retired_from") != null,
                            date(rs.getDate("from_date")), date(rs.getDate("to_date")));
                    found.computeIfAbsent(m.poolId(), k -> new java.util.ArrayList<>()).add(m);
                }, sheetId);
        return found;
    }

    private static LocalDate date(java.sql.Date d) {
        return d == null ? null : d.toLocalDate();
    }

    public Pool find(String sheetId, long id) {
        List<Pool> found = jdbc.query("SELECT id, name FROM pool WHERE sheet_id = ? AND id = ?",
                (rs, i) -> new Pool(rs.getLong("id"), rs.getString("name")), sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    public boolean has(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM pool WHERE sheet_id = ? AND name = ?", Integer.class,
                sheetId, name);
        return n != null && n > 0;
    }

    public void add(String sheetId, String name) {
        jdbc.update("INSERT INTO pool (sheet_id, name) VALUES (?, ?)", sheetId, name);
    }

    public boolean isMember(long poolId, long personId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM pool_member WHERE pool_id = ? AND person_id = ?",
                Integer.class, poolId, personId);
        return n != null && n > 0;
    }

    public void addMember(String sheetId, long poolId, long personId, BigDecimal share, LocalDate from,
            LocalDate to) {
        jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, person_id, share, from_date, to_date)"
                + " VALUES (?, ?, ?, ?, ?, ?)", sheetId, poolId, personId, share, from, to);
    }

    /** Adds the pool {@code memberPoolId} as a member of the pool {@code poolId}. */
    public void addPoolMember(String sheetId, long poolId, long memberPoolId, BigDecimal share, LocalDate from,
            LocalDate to) {
        jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, member_pool_id, share, from_date, to_date)"
                + " VALUES (?, ?, ?, ?, ?, ?)", sheetId, poolId, memberPoolId, share, from, to);
    }

    /** The sheet's pools that are members of another, each to the pool it is a member of. */
    public Map<Long, Long> parents(String sheetId) {
        Map<Long, Long> found = new LinkedHashMap<>();
        jdbc.query("SELECT pool_id, member_pool_id FROM pool_member WHERE sheet_id = ? AND member_pool_id IS NOT NULL",
                rs -> {
                    found.put(rs.getLong("member_pool_id"), rs.getLong("pool_id"));
                }, sheetId);
        return found;
    }

    /** Moves the memberships of {@code fromId} to {@code intoId}, adding the share to theirs in a pool they are
     *  already in. */
    public void merge(String sheetId, long fromId, long intoId) {
        List<Map<String, Object>> rows = jdbc.queryForList(
                "SELECT id, pool_id, share FROM pool_member WHERE sheet_id = ? AND person_id = ? ORDER BY id", sheetId, fromId);
        for (Map<String, Object> row : rows) {
            long poolId = ((Number) row.get("POOL_ID")).longValue();
            long id = ((Number) row.get("ID")).longValue();
            if (isMember(poolId, intoId)) {
                jdbc.update("UPDATE pool_member SET share = share + ? WHERE pool_id = ? AND person_id = ?",
                        row.get("SHARE"), poolId, intoId);
                jdbc.update("DELETE FROM pool_member WHERE id = ?", id);
            } else {
                jdbc.update("UPDATE pool_member SET person_id = ? WHERE id = ?", intoId, id);
            }
        }
    }

    /** Drops the person's pool memberships. */
    public void drop(String sheetId, long personId) {
        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ?", sheetId, personId);
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.crew.CrewStore;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's pools with their members, total share and whether they are balanced, and each member's cut
 *  of the pool's pot: the sheet's pot for a pool that is a member of none, else its cut in the pool above. A
 *  person with a hold in force on the sheet's today (the as-of date when one is given) gets no cut. A member
 *  whose dates do not include that day is left out entirely: not in the total share, not in the balance, no cut.
 *  Each crew is a pool too, after the stored pools in the order the crews were added: under the crew's name (and
 *  the negated crew id), its lead then its members each with an equal share of 100.00 (split as patrons' shares
 *  are, the remainder on the lead), and no dates. */
public class RespondWithPools {
    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, PoolStore store, SettingStore settings,
            PersonStore people, SheetStore sheets, CrewStore crews, ObjectResponse<List<PoolResponse>> response) {
        String sheet = sheetId.trim();
        LocalDate on = History.date(asOf);
        BigDecimal sheetPot = (on == null ? settings : settings.asOf(on)).pot(sheet);
        Map<Long, List<PoolStore.Member>> members = store.members(sheet, on);
        List<PoolStore.Pool> pools = new ArrayList<>(store.list(sheet, on));
        LocalDate today = on == null ? sheets.today(sheet) : on;
        List<Person> everyone = on == null ? people.list(sheet) : people.listAsOf(sheet, on);
        Set<Long> crewPools = addCrews(sheet, on, crews, everyone, pools, members);
        Set<Long> held = everyone.stream()
                .filter(p -> p.getHolds().stream().anyMatch(h -> h.covers(today))).map(Person::getId)
                .collect(Collectors.toSet());
        // each member pool to the pool it is a member of, and its share there
        Map<Long, Long> parents = new HashMap<>();
        members.forEach((poolId, ms) -> ms.stream().filter(m -> m.memberPoolId() != null)
                .forEach(m -> parents.put(m.memberPoolId(), poolId)));
        Map<Long, List<BigDecimal>> cuts = new HashMap<>();
        for (PoolStore.Pool p : pools) {
            cutsOf(p.id(), members, parents, held, today, sheetPot, cuts, 0);
        }
        response.send(pools.stream().map(p -> {
            List<PoolStore.Member> ms = members.getOrDefault(p.id(), List.of());
            List<BigDecimal> cs = cuts.get(p.id());
            List<PoolResponse.MemberResponse> shown = new ArrayList<>();
            for (int i = 0; i < ms.size(); i++) {
                PoolStore.Member m = ms.get(i);
                shown.add(new PoolResponse.MemberResponse(m.personId(), m.memberPoolId(), m.name(),
                        m.share().setScale(2).toPlainString(), m.retired(),
                        cs == null || cs.get(i) == null ? null : cs.get(i).toPlainString(),
                        m.from() == null ? null : m.from().toString(), m.to() == null ? null : m.to().toString()));
            }
            BigDecimal total = total(ms, today);
            return new PoolResponse(p.id(), p.name(), shown, total.toPlainString(), total.compareTo(HUNDRED) == 0,
                    crewPools.contains(p.id()));
        }).toList());
    }

    /** Adds each crew as a pool (id the negated crew id) with its lead and members still on the sheet at equal
     *  shares; the ids of the pools added. */
    private static Set<Long> addCrews(String sheet, LocalDate on, CrewStore crews, List<Person> everyone,
            List<PoolStore.Pool> pools, Map<Long, List<PoolStore.Member>> members) {
        Map<Long, Person> byId = new HashMap<>();
        everyone.forEach(p -> byId.put(p.getId(), p));
        Map<Long, List<CrewStore.Member>> crewMembers = crews.members(sheet, on);
        Set<Long> added = new java.util.HashSet<>();
        for (CrewStore.Crew c : crews.list(sheet, on)) {
            long id = -c.id();
            List<Long> ids = new ArrayList<>();
            ids.add(c.leadId());
            crewMembers.getOrDefault(c.id(), List.of()).forEach(m -> ids.add(m.personId()));
            List<Person> in = ids.stream().map(byId::get).filter(java.util.Objects::nonNull).toList();
            List<BigDecimal> shares = equalShares(in.size());
            List<PoolStore.Member> ms = new ArrayList<>();
            for (int i = 0; i < in.size(); i++) {
                Person p = in.get(i);
                ms.add(new PoolStore.Member(id, p.getId(), null, p.getName(), shares.get(i), p.isRetired(), null,
                        null));
            }
            pools.add(new PoolStore.Pool(id, c.name()));
            members.put(id, ms);
            added.add(id);
        }
        return added;
    }

    /** 100.00 split equally over {@code count}, as patrons' shares are: each the even split rounded half to even
     *  to two decimals, the remainder on the first. */
    private static List<BigDecimal> equalShares(int count) {
        List<BigDecimal> shares = new ArrayList<>();
        if (count == 0) {
            return shares;
        }
        BigDecimal each = HUNDRED.divide(BigDecimal.valueOf(count), 2, RoundingMode.HALF_EVEN);
        for (int i = 0; i < count; i++) {
            shares.add(each);
        }
        shares.set(0, HUNDRED.subtract(each.multiply(BigDecimal.valueOf(count - 1))).setScale(2));
        return shares;
    }

    /** The total of the members' shares, a retired member's counting as given, one whose dates do not include
     *  today as 0.00. */
    private static BigDecimal total(List<PoolStore.Member> ms, LocalDate today) {
        return ms.stream().filter(m -> m.covers(today)).map(PoolStore.Member::share)
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
    }

    /** The pool's members' cuts of its pot, null when it is not balanced or has no pot: the sheet's pot for a
     *  pool that is a member of none, else its cut in the pool above. Kept in {@code cuts} as worked out. */
    private static List<BigDecimal> cutsOf(long poolId, Map<Long, List<PoolStore.Member>> members,
            Map<Long, Long> parents, Set<Long> held, LocalDate today, BigDecimal sheetPot,
            Map<Long, List<BigDecimal>> cuts, int depth) {
        if (cuts.containsKey(poolId) || depth > members.size() + 1) {
            return cuts.get(poolId);
        }
        BigDecimal pot = sheetPot;
        Long parent = parents.get(poolId);
        if (parent != null) {
            List<BigDecimal> above = cutsOf(parent, members, parents, held, today, sheetPot, cuts, depth + 1);
            pot = null;
            List<PoolStore.Member> siblings = members.getOrDefault(parent, List.of());
            for (int i = 0; above != null && i < siblings.size(); i++) {
                if (Long.valueOf(poolId).equals(siblings.get(i).memberPoolId())) {
                    pot = above.get(i);
                }
            }
        }
        List<PoolStore.Member> ms = members.getOrDefault(poolId, List.of());
        List<BigDecimal> found = total(ms, today).compareTo(HUNDRED) == 0 && pot != null ? cuts(ms, held, today, pot) : null;
        cuts.put(poolId, found);
        return found;
    }

    /** Each member's cut, in the members' order: the pot times their share over the shares of the members with a
     *  cut, rounded half to even to two decimals (a retired or held member's is 0.00, their share spread over the
     *  others, and each is 0.00 when none has a cut); null for every member when each whose dates include today is
     *  retired. The remainder goes to the member with the smallest non-zero cut, the latest added on a tie
     *  (a member with no cut gets none; when no cut is non-zero, to the last member with a cut and a share), so
     *  the cuts total exactly the pot. A member whose dates do not include today has no cut (null). */
    private static List<BigDecimal> cuts(List<PoolStore.Member> ms, Set<Long> held, LocalDate today,
            BigDecimal pot) {
        List<PoolStore.Member> current = ms.stream().filter(m -> m.covers(today)).toList();
        if (!current.isEmpty() && current.stream().allMatch(PoolStore.Member::retired)) {
            List<BigDecimal> none = new ArrayList<>();
            ms.forEach(m -> none.add(null));
            return none;
        }
        BigDecimal shares = ms.stream().filter(m -> m.covers(today) && hasCut(m, held)).map(PoolStore.Member::share)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        List<BigDecimal> cuts = new ArrayList<>();
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        int smallest = -1;
        int last = -1;
        for (int i = 0; i < ms.size(); i++) {
            PoolStore.Member m = ms.get(i);
            if (!m.covers(today)) {
                cuts.add(null);
                continue;
            }
            boolean cut = hasCut(m, held) && shares.signum() > 0;
            BigDecimal c = cut ? pot.multiply(m.share()).divide(shares, 2, RoundingMode.HALF_EVEN)
                    : BigDecimal.ZERO.setScale(2);
            cuts.add(c);
            sum = sum.add(c);
            if (cut && m.share().signum() > 0) {
                last = i;
            }
            if (cut && c.signum() > 0 && (smallest < 0 || c.compareTo(cuts.get(smallest)) <= 0)) {
                smallest = i;
            }
        }
        int to = smallest >= 0 ? smallest : last;
        if (to >= 0) {
            cuts.set(to, cuts.get(to).add(pot.subtract(sum)).setScale(2));
        }
        return cuts;
    }

    /** Whether the member gets a cut: not retired, and not a person with a hold in force. */
    private static boolean hasCut(PoolStore.Member m, Set<Long> held) {
        return !m.retired() && (m.personId() == null || !held.contains(m.personId()));
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;

/** A pool as the front end reads it: its members, the total of their shares (a retired member's counts as
 *  given) and whether that total is exactly 100.00. Shares and the total have two decimals. {@code crew} for a
 *  crew shown as a pool (its id the negated crew id): its members are the crew's, and none is added to it here. */
public record PoolResponse(long id, String name, List<MemberResponse> members, String totalShare, boolean balanced,
        boolean crew) {

    /** A member of a pool: the person or the member pool (the other null), its name, its share, and its cut of
     *  the pool's pot (two decimals), null when the pool is not balanced, has no pot or every member is retired. A pool that is a member
     *  of none has the sheet's pot; a member pool's pot is its cut in the pool above. The membership's from- and to-dates, null for no bound; a member whose dates do
     *  not include the sheet's today counts in neither the total nor the balance and has no cut. */
    public record MemberResponse(Long personId, Long memberPoolId, String name, String share, boolean retired,
            String cut, String from, String to) {
    }
}
# GET /api/sheets/{sheetId}/pools — the sheet's pools, in the order they were added, each with its members,
# total share (a retired member's counts as 0.00) and whether it is balanced (exactly 100.00).
# Each crew is a pool too, after the others: its lead and members at equal shares.
