package net.officefloor.hq.app.history;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.stream.Collectors;

/** Reads a table as it stood at the end of a date, from the versions {@link HistoryTrigger} keeps: each row's
 *  last version made while the sheet's today was on or before the date, unless that version deleted it. A
 *  change made while the sheet's today was after the date does not count, whenever it was made. */
public final class History {
    private History() {
    }

    /** The date of an {@code asOf} query parameter (yyyy-MM-dd): null when absent or blank, so the store is
     *  read as it is now. */
    public static LocalDate date(String asOf) {
        return asOf == null || asOf.isBlank() ? null : LocalDate.parse(asOf.trim());
    }

    /** A table expression, named as the table, for use in place of it in a query's FROM: the table's rows
     *  (each identified by {@code keys}, comma separated) as they stood at the end of {@code date}. */
    public static String asOf(String table, String keys, LocalDate date) {
        String on = "DATE '" + date + "'";
        String same = Arrays.stream(keys.split(",")).map(String::trim).map(k -> "l." + k + " = h." + k)
                .collect(Collectors.joining(" AND "));
        return "(SELECT h.* FROM " + table + "_hist h WHERE h.hist_made_on <= " + on + " AND NOT EXISTS (SELECT 1 FROM "
                + table + "_hist l WHERE " + same + " AND l.hist_made_on <= " + on + " AND l.hist_seq > h.hist_seq) AND NOT h.hist_gone) "
                + table;
    }
}
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { useCurrentSheet } from '../../session/session';
import { type Person, usePeople } from '../people/people';
import { dueTotal } from '../rates/rates';
import { type Pool, usePools } from './pools';
import { useFigure } from '../locale/locale';

// A person's cut total (their cuts across every pool they are a member of, a pool showing no cut adding
// nothing) and the sheet's cut total (everyone's added up).
const cutTotal = (pools: Pool[], personId: number) =>
  dueTotal(pools.flatMap((p) => p.members.filter((m) => m.personId === personId && m.cut !== null).map((m) => m.cut as string)));

function CutHead() {
  return <th>Cut total</th>;
}

function PersonCut({ person }: { person: Person }) {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const pools = usePools(sheet);
  return <td data-testid="person-cut-total">{fig(cutTotal(pools.data ?? [], person.id))}</td>;
}

function CutTotal() {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const pools = usePools(sheet);
  return (
    <p>
      Cut total{' '}
      <strong data-testid="rollup-cut-total">{fig(dueTotal((people.data ?? []).map((p) => cutTotal(pools.data ?? [], p.id))))}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 19.96, Component: CutHead }),
  PersonColumns.fill({ order: 19.96, Component: PersonCut }),
  HomeMain.fill({ order: 30.5, Component: CutTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** A member of a pool: a person on the sheet, or another pool (`memberPoolId` set, `personId` null), and its share
 *  percent (two decimals). `retired` once a retirement date is set for them, whatever the date: their share still
 *  counts toward the total. `cut` is their cut of the pool's pot (two decimals; 0.00 when retired or held on the
 *  sheet's today, their share then spread over the members with a cut in proportion to their shares), null when
 *  the pool is not balanced, has no pot, or every member is retired: a pool that is a member of none has the sheet's pot, a member
 *  pool's pot is its cut in the pool above. `from` and `to` bound the dates the membership counts (null for no
 *  bound): a member whose dates do not include the sheet's today counts toward neither the total nor the balance,
 *  and its `cut` is null. */
export type PoolMember = {
  personId: number | null;
  memberPoolId: number | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string | null;
  from: string | null;
  to: string | null;
};

/** A pool on the sheet: its members, the total of their shares (two decimals) and whether it is exactly 100.00.
 *  `crew` for a crew shown as a pool (its id the negated crew id): its members are the crew's lead and members at
 *  equal shares, and no member is added to it here. */
export type Pool = { id: number; name: string; members: PoolMember[]; totalShare: string; balanced: boolean; crew: boolean };

/** Under the sheet's key, so loading the sheet again re-reads its pools. */
export const poolsKey = (sheet: string) => [...sheetKey(sheet), 'pools'] as const;

export function usePools(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(poolsKey(sheet), asOf),
    queryFn: () => getJson<Pool[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/pools`, asOf)),
    enabled: sheet !== '',
  });
}
